#!/usr/bin/env node
// f3-features: converts OpenSpec specs into Gherkin feature files, literally.
//
// Usage, from the project root:
//   node f3-features.mjs                    main specs only (openspec/specs/)
//   node f3-features.mjs <change-id>        main specs with the delta of that change applied
//   node f3-features.mjs --check [<id>]     same conversion, nothing written: reports errors only
//
// Output: tests/e2e/features/<capability-path>.feature, one file per capability.
// A generated file starts with the line "# Generated by f3-features" and is never edited by hand.
// Its content does not depend on whether the delta comes from a change or from the archived specs:
// regenerating after archiving gives identical files.
// Generated files whose capability no longer exists are deleted. Any other file is left alone.
//
// Mapping: capability -> Feature, requirement -> Rule, scenario -> Scenario,
// **GIVEN**/**WHEN**/**THEN**/**AND**/**BUT** bullets -> Given/When/Then/And/But steps.
// The Purpose and the requirement text become comment lines. No text is ever reworded.
//
// Manual scenarios: the scenarios listed in tests/e2e/manual-scenarios.md, one heading
// "## <capability> › <requirement> › <scenario>" per entry, are tagged @manual. An entry that
// matches no scenario, or that lacks its Reason, Replacement coverage or Origin line, is an error.
//
// The script reads files and writes feature files. It runs no other command.
// Exit code: 0 when the conversion succeeds, 1 when at least one error is reported.

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';

const MARK = '# Generated by f3-features';
const root = process.cwd();
const args = process.argv.slice(2);
const check = args.includes('--check');
const changeId = args.find((a) => !a.startsWith('--')) ?? null;
const specsDir = join(root, 'openspec', 'specs');
const featuresDir = join(root, 'tests', 'e2e', 'features');
const errors = [];

const norm = (s) => s.replace(/\s+/g, ' ').trim();
const posix = (p) => p.split(sep).join('/');
const rel = (p) => posix(relative(root, p));

function walk(dir, name) {
  if (!existsSync(dir)) return [];
  const found = [];
  for (const entry of readdirSync(dir).sort()) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) found.push(...walk(full, name));
    else if (name(entry)) found.push(full);
  }
  return found;
}

// Splits the lines of a spec section into requirements.
// Each requirement: { name, text: [lines], scenarios: [{ name, steps: [{ keyword, text }], line }], line }.
function parseRequirements(lines, file) {
  const requirements = [];
  let req = null;
  let sc = null;
  for (const { text, n } of lines) {
    const r = text.match(/^###\s+Requirement:\s*(.+?)\s*$/);
    if (r) {
      req = { name: norm(r[1]), text: [], scenarios: [], line: n };
      requirements.push(req);
      sc = null;
      continue;
    }
    const s = text.match(/^####\s+Scenario:\s*(.+?)\s*$/);
    if (s) {
      if (!req) {
        errors.push(`${rel(file)}:${n}: scenario outside any requirement`);
        continue;
      }
      sc = { name: norm(s[1]), steps: [], line: n };
      req.scenarios.push(sc);
      continue;
    }
    if (!req) continue;
    if (!sc) {
      req.text.push(text);
      continue;
    }
    if (text.trim() === '') continue;
    const step = text.match(/^\s*[-*]\s+\*\*(GIVEN|WHEN|THEN|AND|BUT)\*\*:?\s+(.+?)\s*$/i);
    if (!step) {
      errors.push(`${rel(file)}:${n}: line of scenario "${sc.name}" is not a step (expected "- **GIVEN**", "- **WHEN**", "- **THEN**", "- **AND**" or "- **BUT**" followed by text)`);
      continue;
    }
    sc.steps.push({ keyword: step[1].toUpperCase(), text: step[2], n });
  }
  return requirements;
}

// Checks the order of steps: [GIVEN (AND|BUT)*] WHEN (AND)* THEN (AND|BUT)*.
function checkSteps(sc, file) {
  let state = 'start';
  for (const { keyword, n } of sc.steps) {
    const where = `${rel(file)}:${n}: scenario "${sc.name}"`;
    if (state === 'start') {
      if (keyword === 'GIVEN') state = 'given';
      else if (keyword === 'WHEN') state = 'when';
      else return errors.push(`${where} starts with ${keyword}; a scenario starts with GIVEN or WHEN`);
    } else if (state === 'given') {
      if (keyword === 'WHEN') state = 'when';
      else if (keyword !== 'AND' && keyword !== 'BUT') return errors.push(`${where}: ${keyword} after GIVEN; expected AND, BUT or WHEN`);
    } else if (state === 'when') {
      if (keyword === 'THEN') state = 'then';
      else if (keyword !== 'AND') return errors.push(`${where}: ${keyword} after WHEN; expected AND or THEN`);
    } else if (keyword !== 'AND' && keyword !== 'BUT') {
      return errors.push(`${where}: ${keyword} after THEN; expected AND or BUT`);
    }
  }
  if (state !== 'then') errors.push(`${rel(file)}:${sc.line}: scenario "${sc.name}" has no THEN step`);
}

function numbered(text) {
  return text.split('\n').map((t, i) => ({ text: t, n: i + 1 }));
}

// Main spec: purpose and requirements.
function parseMainSpec(file) {
  const lines = numbered(readFileSync(file, 'utf8'));
  const purpose = [];
  const body = [];
  let section = null;
  for (const line of lines) {
    const h = line.text.match(/^##\s+(.+?)\s*$/);
    if (h && !line.text.startsWith('###')) {
      section = h[1].toLowerCase();
      continue;
    }
    if (section === 'purpose') purpose.push(line.text);
    else if (section === 'requirements') body.push(line);
  }
  return { purpose, requirements: parseRequirements(body, file) };
}

// Delta spec: purpose (new capability), and ADDED, MODIFIED, REMOVED, RENAMED sections.
function parseDelta(file) {
  const lines = numbered(readFileSync(file, 'utf8'));
  const sections = { purpose: [], ADDED: [], MODIFIED: [], REMOVED: [], RENAMED: [] };
  let current = null;
  for (const line of lines) {
    const op = line.text.match(/^##\s+(ADDED|MODIFIED|REMOVED|RENAMED)\s+Requirements\s*$/i);
    if (op) {
      current = op[1].toUpperCase();
      continue;
    }
    if (/^##\s+Purpose\s*$/i.test(line.text)) {
      current = 'purpose';
      continue;
    }
    if (/^##\s+/.test(line.text) && !line.text.startsWith('###')) {
      current = null;
      continue;
    }
    if (current === 'purpose') sections.purpose.push(line.text);
    else if (current) sections[current].push(line);
  }
  const renamed = [];
  let from = null;
  for (const { text, n } of sections.RENAMED) {
    const f = text.match(/FROM:\s*`?\s*(?:###\s+)?Requirement:\s*(.+?)\s*`?\s*$/);
    const t = text.match(/TO:\s*`?\s*(?:###\s+)?Requirement:\s*(.+?)\s*`?\s*$/);
    if (f) from = { name: norm(f[1]), n };
    if (t) {
      if (!from) errors.push(`${rel(file)}:${n}: TO without FROM in RENAMED Requirements`);
      else renamed.push({ from: from.name, to: norm(t[1]), n });
      from = null;
    }
  }
  return {
    purpose: sections.purpose,
    added: parseRequirements(sections.ADDED, file),
    modified: parseRequirements(sections.MODIFIED, file),
    removed: parseRequirements(sections.REMOVED, file),
    renamed,
  };
}

const capabilityOf = (file, base) => posix(relative(base, dirname(file)));

// 1. Main specs.
const capabilities = new Map(); // path -> { purpose, requirements, source }
for (const file of walk(specsDir, (n) => n === 'spec.md')) {
  const spec = parseMainSpec(file);
  capabilities.set(capabilityOf(file, specsDir), { ...spec, source: file });
}

// 2. Delta of the change.
const report = [];
if (changeId) {
  const changeDir = join(root, 'openspec', 'changes', changeId);
  if (!existsSync(changeDir)) {
    console.log(`Error: change "${changeId}" not found in openspec/changes/.`);
    process.exit(1);
  }
  const deltaDir = join(changeDir, 'specs');
  for (const file of walk(deltaDir, (n) => n === 'spec.md')) {
    const cap = capabilityOf(file, deltaDir);
    const delta = parseDelta(file);
    if (!capabilities.has(cap)) {
      capabilities.set(cap, { purpose: delta.purpose, requirements: [], source: file });
    }
    const spec = capabilities.get(cap);
    const index = (name) => spec.requirements.findIndex((r) => r.name === name);
    const ops = { added: [], modified: [], removed: [], renamed: [] };
    for (const { from, to, n } of delta.renamed) {
      const i = index(from);
      if (i < 0) errors.push(`${rel(file)}:${n}: RENAMED requirement "${from}" does not exist in ${cap}`);
      else {
        spec.requirements[i].name = to;
        ops.renamed.push(`${from} -> ${to}`);
      }
    }
    for (const r of delta.removed) {
      const i = index(r.name);
      if (i < 0) errors.push(`${rel(file)}:${r.line}: REMOVED requirement "${r.name}" does not exist in ${cap}`);
      else {
        spec.requirements.splice(i, 1);
        ops.removed.push(r.name);
      }
    }
    for (const r of delta.modified) {
      const i = index(r.name);
      if (i < 0) errors.push(`${rel(file)}:${r.line}: MODIFIED requirement "${r.name}" does not exist in ${cap}`);
      else {
        spec.requirements[i] = r;
        ops.modified.push(r.name);
      }
    }
    for (const r of delta.added) {
      if (index(r.name) >= 0) errors.push(`${rel(file)}:${r.line}: ADDED requirement "${r.name}" already exists in ${cap}`);
      else {
        spec.requirements.push(r);
        ops.added.push(r.name);
      }
    }
    report.push({ cap, ops });
  }
}

// 3. Checks.
for (const [cap, spec] of capabilities) {
  const seen = new Set();
  for (const r of spec.requirements) {
    if (seen.has(r.name)) errors.push(`${cap}: requirement "${r.name}" appears twice`);
    seen.add(r.name);
    if (r.scenarios.length === 0) errors.push(`${cap}: requirement "${r.name}" has no scenario`);
    const names = new Set();
    for (const sc of r.scenarios) {
      if (names.has(sc.name)) errors.push(`${cap}: scenario "${sc.name}" appears twice in requirement "${r.name}"`);
      names.add(sc.name);
      checkSteps(sc, spec.source);
    }
  }
}

// 3b. Manual scenarios register.
const registerFile = join(root, 'tests', 'e2e', 'manual-scenarios.md');
const manual = new Set();
if (existsSync(registerFile)) {
  const ids = new Set();
  for (const [cap, spec] of capabilities) {
    for (const r of spec.requirements) for (const sc of r.scenarios) ids.add(`${cap} › ${r.name} › ${sc.name}`);
  }
  const entries = [];
  let entry = null;
  for (const { text, n } of numbered(readFileSync(registerFile, 'utf8'))) {
    const h = text.match(/^##\s+(.+?)\s*$/);
    if (h && !text.startsWith('###')) {
      const parts = h[1].split('›').map(norm);
      entry = { id: parts.join(' › '), parts, n, fields: new Set() };
      entries.push(entry);
      continue;
    }
    const f = text.match(/^\s*[-*]\s+(Reason|Replacement coverage|Origin):\s*\S/);
    if (f && entry) entry.fields.add(f[1]);
  }
  for (const e of entries) {
    const where = `${rel(registerFile)}:${e.n}`;
    if (e.parts.length !== 3 || e.parts.some((p) => p === '')) {
      errors.push(`${where}: an entry heading is "## <capability> › <requirement> › <scenario>"`);
      continue;
    }
    if (!ids.has(e.id)) errors.push(`${where}: "${e.id}" matches no scenario of the specs; update or remove this entry`);
    for (const field of ['Reason', 'Replacement coverage', 'Origin']) {
      if (!e.fields.has(field)) errors.push(`${where}: entry "${e.id}" has no "${field}:" line`);
    }
    if (manual.has(e.id)) errors.push(`${where}: "${e.id}" is listed twice`);
    manual.add(e.id);
  }
}

// 4. Rendering.
const comment = (lines, indent) =>
  lines
    .map((l) => l.trimEnd())
    .join('\n')
    .trim()
    .split('\n')
    .filter((l, i, all) => !(l === '' && all[i - 1] === ''))
    .map((l) => (l === '' ? `${indent}#` : `${indent}# ${l}`));

function render(cap, spec) {
  const out = [`${MARK} from the OpenSpec specs. Do not edit: regenerate.`, '', `Feature: ${cap}`];
  const purpose = comment(spec.purpose, '  ');
  if (purpose.some((l) => l.trim() !== '#')) out.push(...purpose);
  for (const r of spec.requirements) {
    out.push('', `  Rule: ${r.name}`);
    const text = comment(r.text, '    ');
    if (text.some((l) => l.trim() !== '#')) out.push(...text);
    for (const sc of r.scenarios) {
      out.push('');
      if (manual.has(`${cap} › ${r.name} › ${sc.name}`)) out.push('    @manual');
      out.push(`    Scenario: ${sc.name}`);
      for (const s of sc.steps) {
        const keyword = s.keyword.charAt(0) + s.keyword.slice(1).toLowerCase();
        out.push(`      ${keyword} ${s.text}`);
      }
    }
  }
  return out.join('\n') + '\n';
}

// 5. Output.
if (errors.length > 0) {
  console.log(`f3-features: ${errors.length} error(s). Nothing was written.\n`);
  for (const e of errors) console.log(`- ${e}`);
  process.exit(1);
}

const wanted = new Map();
for (const [cap, spec] of capabilities) {
  if (spec.requirements.length === 0) continue;
  wanted.set(join(featuresDir, `${cap}.feature`), render(cap, spec));
}

const scenarios = [...capabilities.values()].reduce((sum, s) => sum + s.requirements.reduce((n, r) => n + r.scenarios.length, 0), 0);
const lines = [];
lines.push(check ? 'f3-features --check: conversion succeeds, nothing written.' : 'f3-features: feature files generated.');
if (check) lines.push('This check covers the form of the steps only (keywords and order), not the rules of the spec-practice skill.');
lines.push(`Source: openspec/specs${changeId ? ` with the delta of change ${changeId}` : ''}.`);
lines.push(`Capabilities: ${wanted.size}. Scenarios: ${scenarios}, of which manual (tagged @manual): ${manual.size}.`);

if (!check) {
  const stale = walk(featuresDir, (n) => n.endsWith('.feature')).filter(
    (f) => !wanted.has(f) && readFileSync(f, 'utf8').startsWith(MARK),
  );
  for (const f of stale) {
    rmSync(f);
    lines.push(`Deleted (capability no longer exists): ${rel(f)}`);
  }
  for (const [file, content] of wanted) {
    mkdirSync(dirname(file), { recursive: true });
    if (existsSync(file) && !readFileSync(file, 'utf8').startsWith(MARK)) {
      console.log(`Error: ${rel(file)} exists and was not generated by f3-features. Move it, then run again.`);
      process.exit(1);
    }
    writeFileSync(file, content);
  }
  lines.push(`Written: ${[...wanted.keys()].map(rel).join(', ') || 'none'}`);
}

if (changeId) {
  lines.push('', `Delta of change ${changeId}:`);
  if (report.length === 0) lines.push('- no delta spec in this change');
  for (const { cap, ops } of report) {
    for (const [op, names] of Object.entries(ops)) {
      for (const name of names) lines.push(`- ${cap} | ${op} | ${name}`);
    }
  }
}
console.log(lines.join('\n'));
